package dev.openrune.cache.tools.iftype.toml

data class TomlInterfaceHeader(
    val name: Int = 0,
    val inherit: Int? = null,
    val width: Int = 0,
    val height: Int = 0,
    val on_load: List<Any> = emptyList(),
)

data class TomlComponent(
    val name: String,
    val type: String = "layer",
    val parent: String? = null,
    val insert_before: String? = null,
    val insert_after: String? = null,
    val x: Int = 0,
    val y: Int = 0,
    val width: Int = 0,
    val height: Int = 0,
    val x_mode: Int = 0,
    val y_mode: Int = 0,
    val width_mode: Int = 0,
    val height_mode: Int = 0,
    val content_type: Int = 0,
    val hide: Boolean = false,
    val button_type: Int = 0,
    val mouse_over_redirect: Int = -1,
    val op_base: String = "",
    val target_verb: String = "",
    val target_base: String = "",
    val button_text: String = "",
    val drag_dead_zone: Int = 0,
    val drag_dead_time: Int = 0,
    val draggable_behavior: Boolean = false,

    val options: List<String> = emptyList(),
    val events: List<String> = emptyList(),

    val on_load: List<Any> = emptyList(),
    val on_op: List<Any> = emptyList(),
    val on_click: List<Any> = emptyList(),
    val on_click_repeat: List<Any> = emptyList(),
    val on_release: List<Any> = emptyList(),
    val on_hold: List<Any> = emptyList(),
    val on_mouse_over: List<Any> = emptyList(),
    val on_mouse_repeat: List<Any> = emptyList(),
    val on_mouse_leave: List<Any> = emptyList(),
    val on_drag: List<Any> = emptyList(),
    val on_drag_complete: List<Any> = emptyList(),
    val on_target_enter: List<Any> = emptyList(),
    val on_target_leave: List<Any> = emptyList(),
    val on_var_transmit: List<Any> = emptyList(),
    val on_inv_transmit: List<Any> = emptyList(),
    val on_stat_transmit: List<Any> = emptyList(),
    val on_timer: List<Any> = emptyList(),
    val on_scroll_wheel: List<Any> = emptyList(),

    val on_var_transmit_list: List<Int> = emptyList(),
    val on_inv_transmit_list: List<Int> = emptyList(),
    val on_stat_transmit_list: List<Int> = emptyList(),

    val scroll_width: Int = 0,
    val scroll_height: Int = 0,
    val no_click_through: Boolean = false,

    val text: String = "",
    val secondary_text: String = "",
    val font: String = "regular",
    val line_height: Int = 0,
    val h_align: String = "center",
    val v_align: String = "center",
    val text_shadow: Boolean = true,
    val color: String = "",
    val mouse_over_color: String = "",
    val mouse_over_secondary_color: String = "",

    val sprite_id: Int = -1,
    val secondary_sprite_id: Int = -1,
    val texture_id: Int = 0,
    val sprite_tiling: Boolean = false,
    val border_type: Int = 0,
    val shadow_color: String = "",
    val flip_v: Boolean = false,
    val flip_h: Boolean = false,
    val opacity: Int = 0,

    val secondary_color: String = "",
    val filled: Boolean = false,
    val line_width: Int = 1,
    val line_direction: Boolean = false,

    val model_id: Int = -1,
    val model_kind: Int = 1,
    val secondary_model_id: Int = -1,
    val secondary_model_kind: Int = 1,
    val offset_x2d: Int = 0,
    val offset_y2d: Int = 0,
    val rotation_x: Int = 0,
    val rotation_y: Int = 0,
    val rotation_z: Int = 0,
    val model_zoom: Int = 100,
    val animation: Int = -1,
    val secondary_animation: Int = -1,
    val model_height_override: Int = 0,
    val orthogonal: Boolean = false,
)

data class TomlEdit(
    val name: String,
    val x: Int? = null,
    val y: Int? = null,
    val width: Int? = null,
    val height: Int? = null,
    val sprite_id: Int? = null,
    val hide: Boolean? = null,
    val scroll_width: Int? = null,
    val scroll_height: Int? = null,
)

data class TomlInterfaceFile(
    val `interface`: List<TomlInterfaceHeader> = emptyList(),
    val component: List<TomlComponent> = emptyList(),
    val edit: List<TomlEdit> = emptyList(),
)

internal val VALID_COMPONENT_TYPES = setOf("layer", "text", "graphic", "rectangle", "line", "model", "input")
